INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT113-S3-Q8$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Statements$batch13$, $batch13$In every species of higher animal, reproduction requires producing eggs, though not necessarily sperm. Some species are all female. One rare all-female salamander species reproduces without fertilization, so its offspring are near copies of the parent, which makes the species less adaptive than species with both sexes.$batch13$), (1, $batch13$Evaluate$batch13$, $batch13$This is a "could be true EXCEPT" question. Four answers are possible; one contradicts the passage. The firmest rule is the first: every higher-animal species produces eggs.$batch13$), (2, $batch13$Goal$batch13$, $batch13$Find the claim that conflicts with the passage. Look for a higher-animal species without eggs.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT113-S3-Q8$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$One all-female salamander species is rare. Other salamander species can have males and females.$batch13$), ($batch13$B$batch13$, $batch13$Every species of higher animal requires egg production to reproduce, so some members must produce eggs. A species with no egg producers contradicts that.$batch13$), ($batch13$C$batch13$, $batch13$"Rare" describes the salamander species, not all-female species generally. There could be many.$batch13$), ($batch13$D$batch13$, $batch13$Two-sex species are more adaptive than the all-female salamander. That doesn't make every one of them very adaptive.$batch13$), ($batch13$E$batch13$, $batch13$The passage says nothing about how offspring in two-sex species resemble each parent.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT113-S3-Q8$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
